#include <cstdio>

int ds(long long x) { int s = 0; for (; x; x /= 10) s += x % 10; return s; }

int main() {
    long long z;
    if (scanf("%lld", &z) != 1) return 0;
    int target = 2 * ds(z);
    long long x = z + 1;
    while (ds(x) != target) x++;  // first hit in increasing order is the smallest
    printf("%lld\n", x);
}

import java.util.Scanner;

public class Main {
    static int ds(long x) { int s = 0; for (; x > 0; x /= 10) s += x % 10; return s; }

    public static void main(String[] args) {
        long z = new Scanner(System.in).nextLong();
        int target = 2 * ds(z);
        long x = z + 1;
        while (ds(x) != target) x++; // first hit in increasing order is the smallest
        System.out.println(x);
    }
}

package main

import "fmt"

func ds(x int64) int64 {
	var s int64
	for ; x > 0; x /= 10 {
		s += x % 10
	}
	return s
}

func main() {
	var z int64
	fmt.Scan(&z)
	target := 2 * ds(z)
	x := z + 1
	for ds(x) != target { // first hit in increasing order is the smallest
		x++
	}
	fmt.Println(x)
}
